<?php
namespace App\Http\Controllers;
use App\Models\SystemSetting; use App\Services\AuditService; use App\Services\NetworkPolicyService; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage;
class FeatureCompletionSettingsController extends Controller {
 public function update(Request $r,AuditService $audit,NetworkPolicyService $network){$d=$r->validate(['section'=>'required|in:maintenance,branding,network,two_factor,watermark,lifecycle,type_required,audit_retention,recycle_retention,storage_quotas','settings'=>'required|array']);$map=['maintenance'=>'maintenance.settings','branding'=>'branding.settings','network'=>'security.network','two_factor'=>'security.two_factor','watermark'=>'watermark.settings','lifecycle'=>'lifecycle.settings','type_required'=>'metadata.type_required','audit_retention'=>'audit.retention','recycle_retention'=>'recycle.retention','storage_quotas'=>'storage.quotas'];$key=$map[$d['section']];$before=SystemSetting::valueFor($key,[]);$settings=array_replace_recursive($before,$d['settings']);if($d['section']==='network'&&($settings['enabled']??false)){SystemSetting::put($key,$settings);if(!$network->allows($r,$r->user())){SystemSetting::put($key,$before);abort(422,'Network policy would lock out the current Super Admin. Add this IP/CIDR or configure the emergency Super Admin bypass first.');}}else SystemSetting::put($key,$settings);$audit->log($r,'settings.feature-completion.updated',null,'Remaining-feature setting updated.',['section'=>$d['section'],'before'=>$before,'after'=>$settings]);return back()->with('success','Settings saved.');}
 public function logo(Request $r,AuditService $audit){$r->validate(['logo'=>'required|file|mimes:png,jpg,jpeg,webp|max:2048']);$p=$r->file('logo')->store('branding','public');$s=SystemSetting::valueFor('branding.settings',[]);if(!empty($s['logo_path']))Storage::disk('public')->delete($s['logo_path']);$s['logo_path']=$p;SystemSetting::put('branding.settings',$s);$audit->log($r,'branding.logo.updated',null,'Portal logo updated.');return back()->with('success','Logo updated.');}
 public function resetLogo(Request $r,AuditService $audit){$s=SystemSetting::valueFor('branding.settings',[]);if(!empty($s['logo_path']))Storage::disk('public')->delete($s['logo_path']);$s['logo_path']=null;SystemSetting::put('branding.settings',$s);$audit->log($r,'branding.logo.reset',null,'Portal logo reset.');return back()->with('success','Logo reset.');}
}
